// The rules the brief requires, as invariants over { role, term }.
const ROLES = ['follower', 'candidate', 'leader', 'shutdown'];
const same = (a, b) => a.role === b.role && a.term === b.term;

export const stateInvariants = [
  { name: 'role is one of the four roles', pred: (s) => ROLES.includes(s.role) },
  { name: 'term is an integer in 0..3', pred: (s) => Number.isInteger(s.term) && s.term >= 0 && s.term <= 3 },
  // A leader was a candidate first in its own term, so term 0 (no election yet) has no leader.
  { name: 'no leader in term 0', pred: (s) => !(s.role === 'leader' && s.term === 0) },
];

export const transitionInvariants = [
  { name: 'term never goes down', pred: (pre, a, d, post) => post.term >= pre.term },
  {
    name: 'only an election or a newer term changes the term',
    pred: (pre, a, d, post) => post.term === pre.term || a === 'electionTimeout' || a === 'newerTermSeen',
  },
  {
    name: 'an election moves the term up by exactly 1',
    pred: (pre, a, d, post) => a !== 'electionTimeout' || same(pre, post) || (post.term === pre.term + 1 && post.role === 'candidate'),
  },
  {
    name: 'a newer term moves to that term as a follower',
    pred: (pre, a, d, post) => a !== 'newerTermSeen' || same(pre, post) || (post.term === d.term && d.term > pre.term && post.role === 'follower'),
  },
  {
    name: 'a leader was a candidate first in its own term',
    pred: (pre, a, d, post) => post.role !== 'leader' || pre.role === 'leader' || (pre.role === 'candidate' && pre.term === post.term),
  },
  { name: 'a shut down node stays shut down', pred: (pre, a, d, post) => pre.role !== 'shutdown' || same(pre, post) },
  { name: 'shutdown keeps the term', pred: (pre, a, d, post) => post.role !== 'shutdown' || post.term === pre.term },
  { name: 'leader never times out', pred: (pre, a, d, post) => !(a === 'electionTimeout' && pre.role === 'leader') || same(pre, post) },
  { name: 'no election from term 3', pred: (pre, a, d, post) => !(a === 'electionTimeout' && pre.term === 3) || same(pre, post) },
];

