// Drives the real host (src/host.impl.ts) through every command sequence up to DEPTH
// and writes one NDJSON trace per sequence: {pre, action, data, post} per step.
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import createHost from '../src/host.impl.ts';

const DEPTH = 5;
const OUT = new URL('./traces/', import.meta.url);
const steps: { action: string; data: Record<string, number> }[] = [
  { action: 'electionTimeout', data: {} },
  { action: 'electionWon', data: {} },
  { action: 'quorumLost', data: {} },
  { action: 'shutdown', data: {} },
  ...[-1, 0, 1, 2, 3, 4, 1.5].map((term) => ({ action: 'newerTermSeen', data: { term } })),
];

rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });

let n = 0;
const seen = new Set<string>();
async function walk(prefix: number[]): Promise<void> {
  if (prefix.length === DEPTH) return;
  for (let i = 0; i < steps.length; i++) {
    const seq = [...prefix, i];
    const h = await createHost();
    const lines: string[] = [];
    for (const k of seq) {
      const { action, data } = steps[k];
      const pre = await h.node();
      if (action === 'newerTermSeen') await h.newerTermSeen(data.term);
      else await (h as any)[action]();
      const post = await h.node();
      lines.push(JSON.stringify({ pre, action, data, post }));
    }
    // Only keep sequences whose last step reaches a new (pre, action, data) window.
    const key = lines[lines.length - 1];
    if (!seen.has(key)) {
      seen.add(key);
      writeFileSync(new URL(`t${String(n++).padStart(4, '0')}.ndjson`, OUT), lines.join('\n') + '\n');
      await walk(seq);
    }
  }
}
await walk([]);
console.log(`${n} traces written`);

