// The rules the brief requires, as invariants over { role, term, votedFor }.
const ROLES = ['follower', 'candidate', 'leader', 'shutdown'];
const VOTES = ['nobody', 'itself', 'n1', 'n2'];
const PEERS = ['n1', 'n2'];
const same = (a, b) => a.role === b.role && a.term === b.term && a.votedFor === b.votedFor;

export const stateInvariants = [
  { name: 'role is one of the four roles', pred: (s) => ROLES.includes(s.role) },
  { name: 'votedFor is one of the four votes', pred: (s) => VOTES.includes(s.votedFor) },
  { name: 'term is an integer in 0..3', pred: (s) => Number.isInteger(s.term) && s.term >= 0 && s.term <= 3 },
  // A leader was a candidate first in its own term, so term 0 (no election yet) has no leader.
  { name: 'no leader in term 0', pred: (s) => !(s.role === 'leader' && s.term === 0) },
  { name: 'nobody votes in term 0', pred: (s) => s.term !== 0 || s.votedFor === 'nobody' },
  // A candidate or leader started the election of its term, so it voted for itself.
  { name: 'candidates and leaders voted for themselves', pred: (s) => !(s.role === 'candidate' || s.role === 'leader') || s.votedFor === 'itself' },
];

export const transitionInvariants = [
  { name: 'term never goes down', pred: (pre, a, d, post) => post.term >= pre.term },
  {
    name: 'only an election, a newer term or a vote for a newer term changes the term',
    pred: (pre, a, d, post) => post.term === pre.term || ['electionTimeout', 'newerTermSeen', 'voteRequested'].includes(a),
  },
  {
    name: 'an election moves the term up by exactly 1, with a vote for itself',
    pred: (pre, a, d, post) => a !== 'electionTimeout' || same(pre, post) || (post.term === pre.term + 1 && post.role === 'candidate' && post.votedFor === 'itself'),
  },
  {
    name: 'a newer term moves to that term as a follower that has not voted',
    pred: (pre, a, d, post) => a !== 'newerTermSeen' || same(pre, post) || (post.term === d.term && d.term > pre.term && post.role === 'follower' && post.votedFor === 'nobody'),
  },
  {
    name: 'a leader was a candidate first in its own term',
    pred: (pre, a, d, post) => post.role !== 'leader' || pre.role === 'leader' || (pre.role === 'candidate' && pre.term === post.term),
  },
  { name: 'a shut down node stays shut down', pred: (pre, a, d, post) => pre.role !== 'shutdown' || same(pre, post) },
  { name: 'shutdown keeps the term', pred: (pre, a, d, post) => post.role !== 'shutdown' || post.term === pre.term },
  { name: 'leader never times out', pred: (pre, a, d, post) => !(a === 'electionTimeout' && pre.role === 'leader') || same(pre, post) },
  { name: 'no election from term 3', pred: (pre, a, d, post) => !(a === 'electionTimeout' && pre.term === 3) || same(pre, post) },
  // Votes.
  {
    name: 'votes at most once in a term',
    pred: (pre, a, d, post) => post.term !== pre.term || pre.votedFor === 'nobody' || post.votedFor === pre.votedFor,
  },
  {
    name: 'a vote changes only by a vote request, an election or a newer term',
    pred: (pre, a, d, post) => post.votedFor === pre.votedFor || ['voteRequested', 'electionTimeout', 'newerTermSeen'].includes(a),
  },
  {
    name: 'a vote request goes only to n1 or n2 for a term in 1..3',
    pred: (pre, a, d, post) => a !== 'voteRequested' || same(pre, post) || (PEERS.includes(d.candidate) && [1, 2, 3].includes(d.term)),
  },
  {
    name: 'a granted vote is for the requester, in the requested term, as a follower',
    pred: (pre, a, d, post) => a !== 'voteRequested' || same(pre, post) || (post.votedFor === d.candidate && post.term === d.term && post.role === 'follower'),
  },
  {
    name: 'a vote request for a newer term is always granted',
    pred: (pre, a, d, post) => a !== 'voteRequested' || pre.role === 'shutdown' || !PEERS.includes(d.candidate) || ![1, 2, 3].includes(d.term) || d.term <= pre.term || post.votedFor === d.candidate,
  },
  {
    name: 'a vote request in the current term is granted iff a follower that has not voted or voted for that candidate',
    pred: (pre, a, d, post) => {
      if (a !== 'voteRequested' || pre.role === 'shutdown' || !PEERS.includes(d.candidate) || ![1, 2, 3].includes(d.term) || d.term !== pre.term) return true;
      const shouldGrant = pre.role === 'follower' && (pre.votedFor === 'nobody' || pre.votedFor === d.candidate);
      return shouldGrant ? post.votedFor === d.candidate && post.role === 'follower' : same(pre, post);
    },
  },
  { name: 'a vote request for an older term is not granted', pred: (pre, a, d, post) => a !== 'voteRequested' || d.term >= pre.term || same(pre, post) },
];

// Drives the real host (src/host.impl.ts) through every command sequence up to DEPTH
// and writes one NDJSON trace per sequence: {pre, action, data, post} per step.
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import createHost from '../src/host.impl.ts';

const DEPTH = 5;
const OUT = new URL('./traces/', import.meta.url);
const TERMS = [-1, 0, 1, 2, 3, 4, 1.5];
const steps: { action: string; data: { term?: number; candidate?: string } }[] = [
  { action: 'electionTimeout', data: {} },
  { action: 'electionWon', data: {} },
  { action: 'quorumLost', data: {} },
  { action: 'shutdown', data: {} },
  ...TERMS.map((term) => ({ action: 'newerTermSeen', data: { term } })),
  ...['n1', 'n2', 'n3', 'itself'].flatMap((candidate) =>
    TERMS.map((term) => ({ action: 'voteRequested', data: { candidate, term } }))),
];

rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });

let n = 0;
const seen = new Set<string>();
async function walk(prefix: number[]): Promise<void> {
  if (prefix.length === DEPTH) return;
  for (let i = 0; i < steps.length; i++) {
    const seq = [...prefix, i];
    const h = await createHost();
    const lines: string[] = [];
    for (const k of seq) {
      const { action, data } = steps[k];
      const pre = await h.node();
      if (action === 'newerTermSeen') await h.newerTermSeen(data.term!);
      else if (action === 'voteRequested') await h.voteRequested(data.candidate!, data.term!);
      else await (h as any)[action]();
      const post = await h.node();
      lines.push(JSON.stringify({ pre, action, data, post }));
    }
    // Only keep sequences whose last step reaches a new (pre, action, data) window.
    const key = lines[lines.length - 1];
    if (!seen.has(key)) {
      seen.add(key);
      writeFileSync(new URL(`t${String(n++).padStart(4, '0')}.ndjson`, OUT), lines.join('\n') + '\n');
      await walk(seq);
    }
  }
}
await walk([]);
console.log(`${n} traces written`);

