import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('starts a follower in term 0 that has not voted', async () => {
  const h = await createHost();
  assert.deepEqual(await h.node(), { role: 'follower', term: 0, votedFor: 'nobody' });
});

test('election path', async () => {
  const h = await createHost();
  assert.equal((await h.electionWon()).ok, false);
  assert.equal((await h.quorumLost()).ok, false);
  assert.deepEqual(await h.electionTimeout(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'candidate', term: 1, votedFor: 'itself' });
  assert.deepEqual(await h.electionTimeout(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'candidate', term: 2, votedFor: 'itself' });
  assert.deepEqual(await h.electionWon(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'leader', term: 2, votedFor: 'itself' });
  assert.equal((await h.electionTimeout()).ok, false);
  assert.equal((await h.electionWon()).ok, false);
  assert.deepEqual(await h.quorumLost(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 2, votedFor: 'itself' });
  assert.deepEqual(await h.electionTimeout(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'candidate', term: 3, votedFor: 'itself' });
  const r = await h.electionTimeout();
  assert.equal(r.ok, false);
  assert.equal(typeof (r as any).reason, 'string');
  assert.deepEqual(await h.node(), { role: 'candidate', term: 3, votedFor: 'itself' });
});

test('newerTermSeen', async () => {
  const h = await createHost();
  for (const t of [0, 4, -1, 1.5, NaN]) assert.equal((await h.newerTermSeen(t)).ok, false);
  assert.deepEqual(await h.newerTermSeen(2), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 2, votedFor: 'nobody' });
  assert.equal((await h.newerTermSeen(2)).ok, false);
  assert.equal((await h.newerTermSeen(1)).ok, false);
  await h.electionTimeout();
  await h.electionWon();
  assert.deepEqual(await h.node(), { role: 'leader', term: 3, votedFor: 'itself' });
  assert.equal((await h.newerTermSeen(3)).ok, false);
});

test('leader steps down on newer term, and has not voted in it', async () => {
  const h = await createHost();
  await h.electionTimeout();
  await h.electionWon();
  assert.deepEqual(await h.newerTermSeen(3), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 3, votedFor: 'nobody' });
});

test('shutdown is final and keeps the term', async () => {
  const h = await createHost();
  await h.electionTimeout();
  assert.deepEqual(await h.shutdown(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 1, votedFor: 'itself' });
  for (const r of [await h.electionTimeout(), await h.electionWon(), await h.electionLost(),await h.newerTermSeen(3), await h.quorumLost(), await h.shutdown(), await h.voteRequested('n1', 3)]) {
    assert.equal(r.ok, false);
  }
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 1, votedFor: 'itself' });
});

test('fresh systems are independent', async () => {
  const a = await createHost();
  await a.shutdown();
  const b = await createHost();
  assert.deepEqual(await b.node(), { role: 'follower', term: 0, votedFor: 'nobody' });
});

test('vote requests with a bad candidate or term are refused', async () => {
  const h = await createHost();
  for (const [c, t] of [['n3', 1], ['itself', 1], ['nobody', 1], ['', 1], ['n1', 0], ['n1', 4], ['n2', -1], ['n1', 1.5], ['n1', NaN]] as const) {
    const r = await h.voteRequested(c, t);
    assert.equal(r.ok, false, `${c} ${t}`);
    assert.equal(typeof (r as any).reason, 'string');
  }
  assert.deepEqual(await h.node(), { role: 'follower', term: 0, votedFor: 'nobody' });
});

test('a newer term: becomes a follower in it and grants the vote', async () => {
  const h = await createHost();
  assert.deepEqual(await h.voteRequested('n1', 1), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 1, votedFor: 'n1' });
  // From candidate and leader too.
  await h.electionTimeout();
  assert.deepEqual(await h.voteRequested('n2', 3), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 3, votedFor: 'n2' });
  const l = await createHost();
  await l.electionTimeout();
  await l.electionWon();
  assert.deepEqual(await l.voteRequested('n1', 2), { ok: true });
  assert.deepEqual(await l.node(), { role: 'follower', term: 2, votedFor: 'n1' });
});

test('same term: a follower votes at most once, repeats for the same candidate', async () => {
  const h = await createHost();
  await h.newerTermSeen(1);
  assert.deepEqual(await h.voteRequested('n1', 1), { ok: true });
