'use strict';

// SAM v2 strict-profile spec of src/node.ts (the stateful core of src/host.impl.ts).

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const MAX_TERM = 3;
const PEERS = ['n1', 'n2'];
// role: 'follower' | 'candidate' | 'leader' | 'shutdown'
// votedFor: 'nobody' | 'itself' | 'n1' | 'n2' — the vote in the current term
// paused: only a follower is paused; a paused node starts no election
const INITIAL_STATE = { role: 'follower', term: 0, votedFor: 'nobody', paused: false };

const isTerm = (t) => Number.isInteger(t) && t >= 1 && t <= MAX_TERM;

// A fresh definition per intent: SAM tags each action function with its intent.
const noData = () => ({ action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] });

const TERMS = [-1, 0, 1, 2, 3, 4, 1.5];
const CANDIDATES = ['n1', 'n2', 'n3', 'itself'];

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      role: { type: 'string' },
      term: { type: 'number' },
      votedFor: { type: 'string' },
      paused: { type: 'boolean' },
    },
    actions: {
      electionTimeout: noData(),
      electionWon: noData(),
      electionLost: noData(),
      newerTermSeen: {
        action: (data = {}) => ({ ...data }),
        schema: { term: { type: 'number', required: true } },
        domain: TERMS.map((term) => ({ term })),
      },
      quorumLost: noData(),
      shutdown: noData(),
      pause: noData(),
      resume: noData(),
      voteRequested: {
        action: (data = {}) => ({ ...data }),
        schema: { candidate: { type: 'string', required: true }, term: { type: 'number', required: true } },
        domain: CANDIDATES.flatMap((candidate) => TERMS.map((term) => ({ candidate, term }))),
      },
    },
    acceptors: {
      electionTimeout: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        if (model.role === 'leader') return reject('the leader does not time out');
        if (model.paused) return reject('node is paused');
        if (model.term >= MAX_TERM) return reject('no term after 3');
        next.role = 'candidate';
        next.term = model.term + 1;
        next.votedFor = 'itself';
        unchanged('paused');
      },
      electionWon: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        if (model.role !== 'candidate') return reject('only a candidate can win an election');
        next.role = 'leader';
        unchanged('term', 'votedFor', 'paused');
      },
      electionLost: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        if (model.role !== 'candidate') return reject('only a candidate can lose an election');
        next.role = 'follower';
        unchanged('term', 'votedFor', 'paused');
      },
      newerTermSeen: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        const t = proposal.term;
        if (!isTerm(t)) return reject('term must be an integer from 1 to 3');
        if (t <= model.term) return reject('term is not newer');
        next.role = 'follower';
        next.term = t;
        next.votedFor = 'nobody';
        unchanged('paused');
      },
      quorumLost: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        if (model.role !== 'leader') return reject('only the leader can lose its quorum');
        next.role = 'follower';
        unchanged('term', 'votedFor', 'paused');
      },
      shutdown: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        next.role = 'shutdown';
        unchanged('term', 'votedFor', 'paused');
      },
      pause: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        if (model.role !== 'follower') return reject('only a follower can be paused');
        if (model.paused) return reject('node is already paused');
        next.paused = true;
        unchanged('role', 'term', 'votedFor');
      },
      resume: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        if (!model.paused) return reject('node is not paused');
        next.paused = false;
        unchanged('role', 'term', 'votedFor');
      },
      voteRequested: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        const { candidate, term } = proposal;
        if (!PEERS.includes(candidate)) return reject('candidate must be n1 or n2');
        if (!isTerm(term)) return reject('term must be an integer from 1 to 3');
        if (term > model.term) {
          next.role = 'follower';
          next.term = term;
          next.votedFor = candidate;
          unchanged('paused');
          return;
        }
        if (term < model.term) return reject("term is older than the node's term");
        if (model.role !== 'follower') return reject('only a follower grants a vote in its own term');
        if (model.votedFor !== 'nobody' && model.votedFor !== candidate) return reject('already voted in this term');
        next.votedFor = candidate;
        unchanged('role', 'term', 'paused');
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
