import { readFileSync, writeFileSync } from 'node:fs';

const src = readFileSync(new URL('../node.spec.cjs', import.meta.url), 'utf-8');
const mutants = {
  'mutant-leader-times-out': "if (model.role === 'leader') return reject('the leader does not time out');",
  'mutant-votes-twice': "if (model.votedFor !== 'nobody' && model.votedFor !== candidate) return reject('already voted in this term');",
  'mutant-candidate-grants': "if (model.role !== 'follower') return reject('only a follower grants a vote in its own term');",
  'mutant-lost-forgets-vote': "next.role = 'follower';\n        unchanged('term', 'votedFor');\n      },\n      newerTermSeen",
};
const replacements = {
  'mutant-lost-forgets-vote': "next.role = 'follower';\n        next.votedFor = 'nobody';\n        unchanged('term');\n      },\n      newerTermSeen",
};
for (const [name, guard] of Object.entries(mutants)) {
